1	// Isolated critic for the MELEE asset reconstruction loop.
2	//
3	// runCritique is a stateless one-shot pi-ai call: it receives the source
4	// screenshot, extracted reference, current render, extraction prompt, and
5	// asset.json, and returns a structured JSON issue list. The caller is the
6	// scoring authority — the main agent never writes prose critiques or self-
7	// scores; it executes whatever issues come back and renders again.
8	
9	import { readFileSync } from "node:fs";
10	
11	import {
12	  completeSimple,
13	  type Api,
14	  type Context,
15	  type Model,
16	} from "@mariozechner/pi-ai";
17	
18	export type IssueSeverity = "blocking" | "major" | "minor";
19	
20	export interface CritiqueIssue {
21	  id: string;
22	  region: string;
23	  severity: IssueSeverity;
24	  description: string;
25	  fix_hint: string;
26	}
27	
28	export interface CritiqueResult {
29	  issues: CritiqueIssue[];
30	  verdict: string;
31	  raw: string;
32	}
33	
34	export interface RunCritiqueInput {
35	  model: Model<Api>;
36	  auth: { apiKey?: string; headers?: Record<string, string> };
37	  sourcePngPath: string;
38	  extractedPngPath: string;
39	  renderPngPath: string;
40	  extractionPromptText: string;
41	  assetJson: string;
42	  signal?: AbortSignal;
43	}
44	
45	const CRITIC_SYSTEM_PROMPT = `<role>
46	Art-director critic. You compare a rendered HTML/CSS implementation against an
47	extracted game asset reference and report visual defects as structured JSON.
48	You have no memory of prior critiques. Every call is fresh.
49	</role>
50	
51	<inputs_you_receive>
52	1. source.png — original screenshot the asset was cut from. Ground truth for
53	   how the asset looks in situ. Use this when the extraction looks damaged,
54	   bled, or reconstructed wrong where foreground elements occluded regions.
55	2. extracted.png — isolated asset on a solid background. The primary reference
56	   the implementer is matching. Lossy: the extractor may mangle edges, drift
57	   colors slightly, or hallucinate reconstruction.
58	3. render.png — current HTML/CSS render.
59	4. extraction_prompt.txt — prompt used to generate extracted.png. Reveals
60	   whether source/extracted divergence is intentional.
61	5. asset.json — structured metadata. visual_description is authoritative for
62	   what the asset IS.
63	</inputs_you_receive>
64	
65	<category_checks>
66	Walk these first. A category defect is blocking even if pixel-level regional
67	checks pass — a technically close match to the wrong genre is still the wrong
68	asset.
69	
70	- Genre. Does the render read as the same KIND of object as the reference?
71	  MELEE assets have specific visual DNA: chunky borders, hard gradients,
72	  high-contrast fills, projected/tilted planes, glow used deliberately. A
73	  render that matches the color palette but reads as a generic modern UI
74	  panel (soft rounded corners, uniform pastel gradient, subtle drop shadow)
75	  is a blocking genre defect.
76	
77	- Slop signatures. Flag any of these as blocking:
78	  - Left-border accent stripe with soft gradient fill behind it, when the
79	    reference has nothing of the kind.
80	  - Uniform single-direction gradient standing in for a specific multi-stop
81	    gradient in the reference.
82	  - SVG paths attempting to redraw complex illustration or photographic
83	    detail from the reference when a raster region would be honest.
84	  - Corner radius applied uniformly where the reference has mixed corners
85	    (square + rounded, concave + convex).
86	  - Outer drop shadow used as a substitute for the reference's specific
87	    glow treatment.
88	
89	- Color sourcing. Sample dominant fill, border, and glow colors from the
90	  reference. If the render's values look plausible but do not match — even
91	  close — flag as color drift. Invented palettes are a blocking defect when
92	  they shift the asset's overall read, major when they only affect detail.
93	
94	- Projection. If the reference reads as a tilted or foreshortened plane, does
95	  the render match the perspective? A front-on render of a tilted reference
96	  is a blocking projection defect.
97	</category_checks>
98	
99	<regional_checks>
100	After category, walk these for every region of the asset. Compare render.png
101	against extracted.png (source.png is tiebreaker where extraction looks
102	damaged):
103	
104	- Silhouette direction per edge. For top, bottom, left, right edges: does the
105	  reference have tabs, callouts, notches, flanges, or protrusions? For each
106	  feature, state whether it extends OUTward from the panel body or cuts
107	  INward, and whether the render matches. A tab drawn inverted is a blocking
108	  silhouette defect.
109	- Corners. For each of TL, TR, BL, BR: concave (inward indent), convex
110	  (outward bump), square, or rounded? Does the render match?
111	- Dimensional drift. Reference and render should be the same size. Measure
112	  any divergence in pixels along each edge.
113	- Borders and edges. Thickness, hardness, alpha artifacting.
114	- Gradients. Direction, stops, falloff. Multi-stop gradients must be
115	  multi-stop in the render.
116	- Shadows and glows. Spread, intensity, color.
117	- Internal structure. Inner shapes, dividers, ornaments.
118	- Text. Font, weight, stroke, shadow, color, position. Text must be live
119	  text in the render, not rasterized — if it looks rasterized, flag it.
120	- Interior fill. Color, any inner gradient or texture.
121	</regional_checks>
122	
123	<non_issues>
124	Do not flag:
125	- Honest raster placeholders for sub-details the implementer could not
126	  recreate (complex illustration, character portraits, specific iconography).
127	  These will be declared in the implementation's accept notes. Judge only
128	  their color block and size, not their content.
129	- Subpixel differences in antialiasing that are invisible at native size.
130	- Font hinting differences when the correct font family is rendering.
131	- Minor wrapper-level whitespace as long as the asset bounds are correct.
132	
133	If you are unsure whether something is a real defect vs. an artifact of
134	extraction or rendering, check source.png. If the feature is present in the
135	source but not in extracted.png, the extractor is at fault and the render
136	should match source.png.
137	</non_issues>
138	
139	<severity_rules>
140	- blocking: genre defect, slop signature, silhouette-direction mismatch,
141	  wrong projection, inverted corner, missing required structural element,
142	  wrong aspect ratio, color drift that shifts the asset's overall read.
143	- major: clearly visible color drift in detail, missing visual layer (glow,
144	  inner shadow, specific border treatment), dimensional drift >4px on any
145	  edge, wrong text position, rasterized text that should be live.
146	- minor: small color drift, soft gradient falloff mismatch, subpixel edge
147	  softness, small text-shadow differences.
148	
149	If you are unsure whether something is a defect, err toward reporting it.
150	False positives are cheap; silent failures are expensive.
151	</severity_rules>
152	
153	<reply_format>
154	Return a single JSON object and nothing else — no prose before or after, no
155	markdown fences. Shape:
156	
157	{
158	  "verdict": "one sentence overall read of the match",
159	  "issues": [
160	    {
161	      "id": "I1",
162	      "region": "genre" | "slop" | "projection" | "top_edge" | "bottom_edge" | "left_edge" | "right_edge" | "top_left_corner" | "top_right_corner" | "bottom_left_corner" | "bottom_right_corner" | "tab_callout" | "interior_fill" | "border" | "glow" | "shadow" | "text" | "gradient" | "dimensional" | "color" | "other",
163	      "severity": "blocking" | "major" | "minor",
164	      "description": "what is wrong, named concretely",
165	      "fix_hint": "one-sentence suggestion; the implementer picks the actual fix"
166	    }
167	  ]
168	}
169	
170	When the render matches the reference well enough to ship, return:
171	{ "verdict": "...", "issues": [] }
172	
173	An empty issues array is the convergence signal. Use it only when you have
174	actually walked every category check AND every regional check and found no
175	defect worth reporting.
176	</reply_format>`;
177	
178	const REPLY_INSTRUCTION = `Walk every check in <what_to_check> against the three images. Return the JSON object described in <reply_format>. No prose, no markdown fences — JSON only.`;
179	
180	export async function runCritique(
181	  input: RunCritiqueInput,
182	): Promise<CritiqueResult> {
183	  const sourceBase64 = readFileSync(input.sourcePngPath).toString("base64");
184	  const extractedBase64 = readFileSync(input.extractedPngPath).toString(
185	    "base64",
186	  );
187	  const renderBase64 = readFileSync(input.renderPngPath).toString("base64");
188	
189	  const userText = [
190	    "Images follow in this order: source screenshot, extracted reference, current render.",
191	    "",
192	    "extraction_prompt.txt:",
193	    input.extractionPromptText.trim(),
194	    "",
195	    "asset.json:",
196	    input.assetJson.trim(),
197	    "",
198	    REPLY_INSTRUCTION,
199	  ].join("\n");
200	
201	  const context: Context = {
202	    systemPrompt: CRITIC_SYSTEM_PROMPT,
203	    messages: [
204	      {
205	        role: "user",
206	        content: [
207	          { type: "text", text: "source.png (ground truth in situ):" },
208	          { type: "image", data: sourceBase64, mimeType: "image/png" },
209	          { type: "text", text: "extracted.png (primary reference):" },
210	          { type: "image", data: extractedBase64, mimeType: "image/png" },
211	          { type: "text", text: "render.png (current implementation):" },
212	          { type: "image", data: renderBase64, mimeType: "image/png" },
213	          { type: "text", text: userText },
214	        ],
215	        timestamp: Date.now(),
216	      },
217	    ],
218	  };
219	
220	  const first = await completeSimple(input.model, context, {
221	    apiKey: input.auth.apiKey,
222	    headers: input.auth.headers,
223	    reasoning: "high",
224	    signal: input.signal,
225	  });
226	  const firstText = extractText(first.content);
227	  const firstParsed = tryParse(firstText);
228	  if (firstParsed) {
229	    return { ...firstParsed, raw: firstText };
230	  }
231	
232	  // One retry with stricter instruction.
233	  const retryContext: Context = {
234	    systemPrompt: CRITIC_SYSTEM_PROMPT,
235	    messages: [
236	      ...context.messages,
237	      {
238	        role: "assistant",
239	        content: [{ type: "text", text: firstText }],
240	        api: first.api,
241	        provider: first.provider,
242	        model: first.model,
243	        usage: first.usage,
244	        stopReason: first.stopReason,
245	        timestamp: Date.now(),
246	      },
247	      {
248	        role: "user",
249	        content: [
250	          {
251	            type: "text",
252	            text: "Your previous reply was not valid JSON. Return the JSON object described in <reply_format> and nothing else. No prose, no markdown fences.",
253	          },
254	        ],
255	        timestamp: Date.now(),
256	      },
257	    ],
258	  };
259	
260	  const second = await completeSimple(input.model, retryContext, {
261	    apiKey: input.auth.apiKey,
262	    headers: input.auth.headers,
263	    reasoning: "high",
264	    signal: input.signal,
265	  });
266	  const secondText = extractText(second.content);
267	  const secondParsed = tryParse(secondText);
268	  if (secondParsed) {
269	    return { ...secondParsed, raw: secondText };
270	  }
271	
272	  return {
273	    issues: [
274	      {
275	        id: "I1",
276	        region: "other",
277	        severity: "blocking",
278	        description: `Critic returned unparseable JSON twice. Raw reply: ${truncate(secondText, 400)}`,
279	        fix_hint:
280	          "Render again and call critique; the next critic call starts fresh.",
281	      },
282	    ],
283	    verdict: "Critic parse failure — treat as unconverged.",
284	    raw: secondText,
285	  };
286	}
287	
288	function extractText(content: Array<{ type: string; text?: string }>): string {
289	  return content
290	    .filter((c) => c.type === "text" && typeof c.text === "string")
291	    .map((c) => c.text as string)
292	    .join("\n")
293	    .trim();
294	}
295	
296	function tryParse(text: string): Omit<CritiqueResult, "raw"> | null {
297	  const stripped = stripFences(text).trim();
298	  const jsonCandidate = extractJsonObject(stripped);
299	  if (!jsonCandidate) return null;
300	  let parsed: unknown;
301	  try {
302	    parsed = JSON.parse(jsonCandidate);
303	  } catch {
304	    return null;
305	  }
306	  if (!parsed || typeof parsed !== "object") return null;
307	  const obj = parsed as Record<string, unknown>;
308	  const verdict = typeof obj.verdict === "string" ? obj.verdict : "";
309	  const rawIssues = Array.isArray(obj.issues) ? obj.issues : null;
310	  if (rawIssues === null) return null;
311	  const issues: CritiqueIssue[] = [];
312	  for (let i = 0; i < rawIssues.length; i++) {
313	    const normalized = normalizeIssue(rawIssues[i], i);
314	    if (normalized) issues.push(normalized);
315	  }
316	  return { verdict, issues };
317	}
318	
319	function normalizeIssue(raw: unknown, index: number): CritiqueIssue | null {
320	  if (!raw || typeof raw !== "object") return null;
321	  const r = raw as Record<string, unknown>;
322	  const severity = normalizeSeverity(r.severity);
323	  if (!severity) return null;
324	  return {
325	    id: typeof r.id === "string" && r.id.length > 0 ? r.id : `I${index + 1}`,
326	    region:
327	      typeof r.region === "string" && r.region.length > 0 ? r.region : "other",
328	    severity,
329	    description: typeof r.description === "string" ? r.description : "",
330	    fix_hint: typeof r.fix_hint === "string" ? r.fix_hint : "",
331	  };
332	}
333	
334	function normalizeSeverity(v: unknown): IssueSeverity | null {
335	  if (v === "blocking" || v === "major" || v === "minor") return v;
336	  return null;
337	}
338	
339	function stripFences(text: string): string {
340	  const fence = /^```(?:json)?\s*([\s\S]*?)\s*```$/m;
341	  const match = text.trim().match(fence);
342	  return match ? match[1]! : text;
343	}
344	
345	function extractJsonObject(text: string): string | null {
346	  const start = text.indexOf("{");
347	  if (start < 0) return null;
348	  let depth = 0;
349	  let inString = false;
350	  let escape = false;
351	  for (let i = start; i < text.length; i++) {
352	    const ch = text[i]!;
353	    if (escape) {
354	      escape = false;
355	      continue;
356	    }
357	    if (ch === "\\") {
358	      escape = true;
359	      continue;
360	    }
361	    if (ch === '"') {
362	      inString = !inString;
363	      continue;
364	    }
365	    if (inString) continue;
366	    if (ch === "{") depth++;
367	    else if (ch === "}") {
368	      depth--;
369	      if (depth === 0) return text.slice(start, i + 1);
370	    }
371	  }
372	  return null;
373	}
374	
375	function truncate(s: string, max: number): string {
376	  if (s.length <= max) return s;
377	  return `${s.slice(0, max)}…`;
378	}
379

