        ? "critic returned zero issues"
        : `iteration cap reached with ${outstandingIssues.length} residual issue(s)`;
      return {
        content: [
          {
            type: "text" as const,
            text: `Accepted asset ${resolved.assetId} after ${iteration} iteration(s) — ${reason}. Wrote ${resolved.acceptedJsonPath}.`,
          },
        ],
        details: payload,
      };
    },
