// Resolves an asset dir produced by apps/asset-extraction-pipeline and finds
// the extracted reference image (structured path first, legacy root fallback).

import { existsSync, readFileSync } from "node:fs";
import { isAbsolute, resolve } from "node:path";

export interface ResolvedAsset {
  assetId: string;
  assetDir: string;
  assetJsonPath: string;
  extractedPngPath: string;
  sourcePngPath: string;
  extractionPromptPath: string;
  componentHtmlPath: string;
  componentCssPath: string;
  renderPath: string;
  wrapperPath: string;
  acceptedJsonPath: string;
  critiqueJsonPath: string;
}

export interface ResolveInput {
  asset: string | undefined;
  run: string | undefined;
  cwd: string;
}

export function resolveAsset(input: ResolveInput): ResolvedAsset {
  if (!input.asset) {
    throw new Error("--asset is required (path to asset dir or bare id with --run)");
  }

  const assetDir = resolveAssetDir(input.asset, input.run, input.cwd);
  if (!existsSync(assetDir)) {
    throw new Error(`Asset dir not found: ${assetDir}`);
  }

  const assetJsonPath = resolve(assetDir, "asset.json");
  if (!existsSync(assetJsonPath)) {
    throw new Error(`Missing asset metadata: ${assetJsonPath}`);
  }

  const extractedPngPath = resolveExtractedPng(assetDir);
  const sourcePngPath = resolveSourcePng(assetDir);
  const extractionPromptPath = resolveExtractionPrompt(assetDir);

  const assetId = parseAssetId(assetJsonPath) ?? assetDir.split("/").pop() ?? "asset";

  return {
    assetId,
    assetDir,
    assetJsonPath,
    extractedPngPath,
    sourcePngPath,
    extractionPromptPath,
    componentHtmlPath: resolve(assetDir, "component.html"),
    componentCssPath: resolve(assetDir, "component.css"),
    renderPath: resolve(assetDir, "render.png"),
    wrapperPath: resolve(assetDir, "wrapper.html"),
    acceptedJsonPath: resolve(assetDir, "accepted.json"),
    critiqueJsonPath: resolve(assetDir, "critique.json"),
  };
}

function resolveSourcePng(assetDir: string): string {
  const candidate = resolve(assetDir, "..", "..", "source.png");
  if (!existsSync(candidate)) {
    throw new Error(`Missing source screenshot: ${candidate}`);
  }
  return candidate;
}

function resolveExtractionPrompt(assetDir: string): string {
  const candidate = resolve(assetDir, "extraction", "prompt_generation", "prompt.txt");
  if (!existsSync(candidate)) {
    throw new Error(`Missing extraction prompt: ${candidate}`);
  }
  return candidate;
}

function resolveAssetDir(asset: string, run: string | undefined, cwd: string): string {
  const looksLikePath = asset.includes("/") || isAbsolute(asset) || existsSync(asset);
  if (looksLikePath) {
    return resolve(cwd, asset);
  }
  if (!run) {
    throw new Error(`--asset "${asset}" looks like a bare id; also pass --run <run-dir>`);
  }
  return resolve(cwd, run, "assets", asset);
}

function resolveExtractedPng(assetDir: string): string {
  const structured = resolve(assetDir, "extraction", "image_extraction", "extracted.png");
  if (existsSync(structured)) return structured;
  const legacy = resolve(assetDir, "extracted.png");
  if (existsSync(legacy)) return legacy;
  throw new Error(`Missing extracted asset image: ${structured}`);
}

function parseAssetId(assetJsonPath: string): string | undefined {
  try {
    const raw = readFileSync(assetJsonPath, "utf8");
    const data = JSON.parse(raw) as { id?: unknown };
    return typeof data.id === "string" ? data.id : undefined;
  } catch {
    return undefined;
  }
}

const { session } = await createAgentSession();

// Custom: override specific options
const { session } = await createAgentSession({
  model: myModel,
  tools: [readTool, bashTool],
  sessionManager: SessionManager.inMemory(),
});
```

### AgentSession

The session manages the agent lifecycle, message history, and event streaming.

```typescript
interface AgentSession {
  // Send a prompt and wait for completion
  // If streaming, requires streamingBehavior option to queue the message
  prompt(text: string, options?: PromptOptions): Promise<void>;

  // Queue messages during streaming
  steer(text: string): Promise<void>;    // Interrupt: delivered after current tool, skips remaining
  followUp(text: string): Promise<void>; // Wait: delivered only when agent finishes

  // Subscribe to events (returns unsubscribe function)
  subscribe(listener: (event: AgentSessionEvent) => void): () => void;

  // Session info
  sessionFile: string | undefined;  // undefined for in-memory
  sessionId: string;

  // Model control
  setModel(model: Model): Promise<void>;
  setThinkingLevel(level: ThinkingLevel): void;
  cycleModel(): Promise<ModelCycleResult | undefined>;
  cycleThinkingLevel(): ThinkingLevel | undefined;

  // State access
  agent: Agent;
  model: Model | undefined;
  thinkingLevel: ThinkingLevel;
  messages: AgentMessage[];
  isStreaming: boolean;

  // Session management
  newSession(options?: { parentSession?: string }): Promise<boolean>;  // Returns false if cancelled by hook
  switchSession(sessionPath: string): Promise<boolean>;

  // Forking
  fork(entryId: string): Promise<{ selectedText: string; cancelled: boolean }>;  // Creates new session file
  navigateTree(targetId: string, options?: { summarize?: boolean; customInstructions?: string; replaceInstructions?: boolean; label?: string }): Promise<{ editorText?: string; cancelled: boolean }>;  // In-place navigation

  // Hook message injection
  sendHookMessage(message: HookMessage, triggerTurn?: boolean): Promise<void>;

  // Compaction
  compact(customInstructions?: string): Promise<CompactionResult>;
  abortCompaction(): void;

  // Abort current operation
  abort(): Promise<void>;

  // Cleanup
  dispose(): void;
}
```

### Prompting and Message Queueing

The `prompt()` method handles prompt templates, extension commands, and message sending:

```typescript
// Basic prompt (when not streaming)
await session.prompt("What files are here?");

// With images
await session.prompt("What's in this image?", {
  images: [{ type: "image", source: { type: "base64", mediaType: "image/png", data: "..." } }]
});

// During streaming: must specify how to queue the message
await session.prompt("Stop and do this instead", { streamingBehavior: "steer" });
await session.prompt("After you're done, also check X", { streamingBehavior: "followUp" });
```

**Behavior:**
- **Extension commands** (e.g., `/mycommand`): Execute immediately, even during streaming. They manage their own LLM interaction via `pi.sendMessage()`.
- **File-based prompt templates** (from `.md` files): Expanded to their content before sending/queueing.
- **During streaming without `streamingBehavior`**: Throws an error. Use `steer()` or `followUp()` directly, or specify the option.

For explicit queueing during streaming:

```typescript
// Interrupt the agent (delivered after current tool, skips remaining tools)
await session.steer("New instruction");

// Wait for agent to finish (delivered only when agent stops)
await session.followUp("After you're done, also do this");
```

Both `steer()` and `followUp()` expand file-based prompt templates but error on extension commands (extension commands cannot be queued).

### Agent and AgentState

The `Agent` class (from `@mariozechner/pi-agent-core`) handles the core LLM interaction. Access it via `session.agent`.

```typescript
// Access current state
const state = session.agent.state;

// state.messages: AgentMessage[] - conversation history
// state.model: Model - current model
// state.thinkingLevel: ThinkingLevel - current thinking level
// state.systemPrompt: string - system prompt
// state.tools: Tool[] - available tools

// Replace messages (useful for branching, restoration)
session.agent.replaceMessages(messages);

// Wait for agent to finish processing
await session.agent.waitForIdle();
```

### Events

Subscribe to events to receive streaming output and lifecycle notifications.

```typescript
session.subscribe((event) => {
  switch (event.type) {
    // Streaming text from assistant
    case "message_update":
      if (event.assistantMessageEvent.type === "text_delta") {
        process.stdout.write(event.assistantMessageEvent.delta);
      }
      if (event.assistantMessageEvent.type === "thinking_delta") {
        // Thinking output (if thinking enabled)
      }
      break;

    // Tool execution
    case "tool_execution_start":
      console.log(`Tool: ${event.toolName}`);
      break;
    case "tool_execution_update":
      // Streaming tool output
      break;
    case "tool_execution_end":
      console.log(`Result: ${event.isError ? "error" : "success"}`);
      break;

    // Message lifecycle
    case "message_start":
      // New message starting
      break;
    case "message_end":
      // Message complete
      break;

    // Agent lifecycle
    case "agent_start":
      // Agent started processing prompt
      break;
    case "agent_end":
      // Agent finished (event.messages contains new messages)
      break;

    // Turn lifecycle (one LLM response + tool calls)
    case "turn_start":
      break;
    case "turn_end":
      // event.message: assistant response
      // event.toolResults: tool results from this turn
      break;

    // Session events (auto-compaction, retry)
    case "auto_compaction_start":
    case "auto_compaction_end":
    case "auto_retry_start":
    case "auto_retry_end":
      break;
  }
});
```

## Options Reference

### Directories

```typescript
const { session } = await createAgentSession({
  // Working directory for DefaultResourceLoader discovery
  cwd: process.cwd(), // default

  // Global config directory
  agentDir: "~/.pi/agent", // default (expands ~)
});
```

`cwd` is used by `DefaultResourceLoader` for:

/**
 * Full Control
 *
 * Replace everything - no discovery, explicit configuration.
 *
 * IMPORTANT: When providing `tools` with a custom `cwd`, use the tool factory
 * functions (createReadTool, createBashTool, etc.) to ensure tools resolve
 * paths relative to your cwd.
 */

import { getModel } from "@mariozechner/pi-ai";
import {
	AuthStorage,
	createAgentSession,
	createBashTool,
	createExtensionRuntime,
	createReadTool,
	ModelRegistry,
	type ResourceLoader,
	SessionManager,
	SettingsManager,
} from "@mariozechner/pi-coding-agent";

// Custom auth storage location
const authStorage = AuthStorage.create("/tmp/my-agent/auth.json");

// Runtime API key override (not persisted)
if (process.env.MY_ANTHROPIC_KEY) {
	authStorage.setRuntimeApiKey("anthropic", process.env.MY_ANTHROPIC_KEY);
}

// Model registry with no custom models.json
const modelRegistry = new ModelRegistry(authStorage);

const model = getModel("anthropic", "claude-sonnet-4-20250514");
if (!model) throw new Error("Model not found");

// In-memory settings with overrides
const settingsManager = SettingsManager.inMemory({
	compaction: { enabled: false },
	retry: { enabled: true, maxRetries: 2 },
});

// When using a custom cwd with explicit tools, use the factory functions
const cwd = process.cwd();

const resourceLoader: ResourceLoader = {
	getExtensions: () => ({ extensions: [], errors: [], runtime: createExtensionRuntime() }),
	getSkills: () => ({ skills: [], diagnostics: [] }),
	getPrompts: () => ({ prompts: [], diagnostics: [] }),
	getThemes: () => ({ themes: [], diagnostics: [] }),
	getAgentsFiles: () => ({ agentsFiles: [] }),
	getSystemPrompt: () => `You are a minimal assistant.
Available: read, bash. Be concise.`,
	getAppendSystemPrompt: () => [],
	getPathMetadata: () => new Map(),
	extendResources: () => {},
	reload: async () => {},
};

const { session } = await createAgentSession({
	cwd,
	agentDir: "/tmp/my-agent",
	model,
	thinkingLevel: "off",
	authStorage,
	modelRegistry,
	resourceLoader,
	// Use factory functions with the same cwd to ensure path resolution works correctly
	tools: [createReadTool(cwd), createBashTool(cwd)],
	sessionManager: SessionManager.inMemory(),
	settingsManager,
});

session.subscribe((event) => {
	if (event.type === "message_update" && event.assistantMessageEvent.type === "text_delta") {
		process.stdout.write(event.assistantMessageEvent.delta);
	}
});

await session.prompt("List files in the current directory.");
console.log();

